// =========================================
// SERPAPI GOOGLE MAPS DATA TRANSFORMATION
// Dynamic Research | Maximum 4 Businesses
// =========================================

// 1. Read SerpApi response
const input = $input.all();

// 2. Get dynamic form information
const form = $("Edit Fields").first().json;

const researchTopic = form["Research Topic"] || "";
const category = form["Catagory"] || "";
const country = form["What is your Country"] || "";

// 3. Settings
const MAX_BUSINESSES = 4;

// 4. Helper functions
function cleanText(value) {
  if (value === undefined || value === null) {
    return null;
  }

  const text = String(value)
    .replace(/\s+/g, " ")
    .trim();

  return text || null;
}

function cleanNumber(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number) ? number : null;
}

// 5. Extract business results from SerpApi
const allBusinesses = [];

for (const item of input) {
  const data = item.json;

  if (Array.isArray(data.local_results)) {
    allBusinesses.push(...data.local_results);
  }

  if (data.place_results) {
    allBusinesses.push(data.place_results);
  }
}

// 6. Remove duplicate businesses
const uniqueBusinesses = [];
const seen = new Set();

for (const business of allBusinesses) {
  const name = cleanText(business.title);

  if (!name) continue;

  const key = business.place_id ||
    business.data_id ||
    `${name.toLowerCase()}|${business.address || ""}`;

  if (seen.has(key)) continue;

  seen.add(key);
  uniqueBusinesses.push(business);
}

// 7. Select first 4 search results
const selectedBusinesses = uniqueBusinesses.slice(
  0,
  MAX_BUSINESSES
);

// 8. Transform every business into a separate item
const output = selectedBusinesses.map((business, index) => {

  return {
    json: {

      // Research context
      research_context: {
        research_topic: researchTopic,
        business_category: category,
        country: country
      },

      // Business identification
      rank: index + 1,

      business_name: cleanText(business.title),

      business_type: cleanText(business.type),

      business_types: Array.isArray(business.types)
        ? business.types
        : [],

      // Location
      address: cleanText(business.address),

      location: {
        latitude: cleanNumber(
          business.gps_coordinates?.latitude
        ),

        longitude: cleanNumber(
          business.gps_coordinates?.longitude
        )
      },

      // Contact
      phone: cleanText(
        business.phone || business.links?.phone
      ),

      website: cleanText(
        business.website || business.links?.website
      ),

      // Ratings
      google_overall_rating: cleanNumber(
        business.rating
      ),

      google_total_review_count: cleanNumber(
        business.reviews
      ),

      // SerpApi identifiers
      place_id: business.place_id || null,

      data_id: business.data_id || null,

      reviews_link: business.reviews_link || null,

      place_id_search: business.place_id_search || null,

      // Extra information
      description: cleanText(business.description),

      price: cleanText(business.price),

      operating_hours:
        business.operating_hours ||
        business.hours ||
        null,

      // Source
      data_source: "SerpApi Google Maps",

      data_status: "Collected"
    }
  };
});

// 9. Handle missing results
if (output.length === 0) {
  return [{
    json: {
      data_status: "No businesses found",
      business_count: 0,
      research_context: {
        research_topic: researchTopic,
        business_category: category,
        country: country
      },
      error: "SerpApi returned no local_results"
    }
  }];
}

// 10. Return transformed businesses
return output;

// ==========================================
// N8N MARKET RESEARCH
// PREPARE DATA FOR AI AGENT
// ==========================================

const MAX_BUSINESSES = 4;
const MAX_REVIEWS = 5;

// 1. Get dynamic form values
const form = $("Edit Fields").first().json;

const researchContext = {
  research_topic: form["Research Topic"] || "",
  business_category:
    form["Catagory"] || form["Category"] || "",
  country: form["What is your Country"] || ""
};

// 2. Read Aggregate data
const inputItems = $input.all();

const records = inputItems.flatMap(item => {
  const data = item.json;

  if (Array.isArray(data.data)) {
    return data.data;
  }

  if (Array.isArray(data.items)) {
    return data.items;
  }

  return [data];
});

// 3. Normalize all businesses
const businesses = records
  .map((record, index) => {

    const data = record.json || record;

    const original =
      data.original_business ||
      data.business ||
      data;

    const serpapi = data.serpapi_result || {};

    const reviewsRaw =
      original.customer_reviews ||
      data.customer_reviews ||
      data.reviews ||
      [];

    const reviews = Array.isArray(reviewsRaw)
      ? reviewsRaw.slice(0, MAX_REVIEWS).map(review => ({
          rating:
            review.rating ??
            review.stars ??
            null,

          text: String(
            review.text ||
            review.snippet ||
            review.review ||
            ""
          ).slice(0, 300),

          date:
            review.date ||
            review.iso_date ||
            null
        }))
      : [];

    const name =
      original.business_name ||
      original.title ||
      serpapi.business_name ||
      "";

    const validation = data.validation || {};

    return {
      rank: index + 1,

      business_name: name,

      business_type:
        original.business_type ||
        serpapi.business_type ||
        "",

      address:
        original.address ||
        serpapi.address ||
        "",

      phone:
        original.phone ||
        serpapi.phone ||
        "",

      website:
        original.website ||
        serpapi.website ||
        "",

      google_rating:
        original.google_overall_rating ??
        original.rating ??
        serpapi.rating ??
        null,

      total_google_reviews:
        original.google_total_review_count ??
        original.reviews_count ??
        serpapi.reviews_count ??
        null,

      google_maps_url:
        original.google_maps_url ||
        serpapi.google_maps_url ||
        "",

      place_id:
        original.place_id ||
        serpapi.place_id ||
        "",

      validation_status:
        validation.is_valid === true
          ? "verified"
          : "unverified",

      validation_reason:
        validation.reason || "",

      reviews_sampled: reviews.length,

      customer_reviews: reviews
    };
  })

  // Remove only records without a business name
  .filter(business => business.business_name)

  // Keep maximum 4 businesses
  .slice(0, MAX_BUSINESSES);

// 4. Calculate statistics
const ratings = businesses
  .map(business => Number(business.google_rating))
  .filter(rating => Number.isFinite(rating) && rating > 0);

const averageRating = ratings.length
  ? Number(
      (
        ratings.reduce((sum, rating) => sum + rating, 0)
        / ratings.length
      ).toFixed(2)
    )
  : null;

const totalReviewsSampled = businesses.reduce(
  (sum, business) => sum + business.reviews_sampled,
  0
);

// 5. Prepare AI analysis object
const aiData = {

  research_context: researchContext,

  analysis_type:
    "Professional Local Business Market Research",

  statistics: {
    businesses_found: businesses.length,
    reviews_sampled: totalReviewsSampled,
    average_google_rating: averageRating
  },

  businesses: businesses,

  analysis_instructions: [
    "Analyze each business separately.",
    "Compare strengths and weaknesses.",
    "Identify customer satisfaction patterns.",
    "Identify common complaints from available reviews.",
    "Evaluate competitive positioning.",
    "Suggest business improvement opportunities.",
    "Provide a professional executive summary.",
    "Provide actionable recommendations.",
    "Clearly distinguish observed facts from interpretations.",
    "Do not invent missing information.",
    "Treat unverified listings as unverified."
  ],

  limitations: [
    "Google Maps ratings and review counts may change.",
    "Sampled reviews may not represent all customers.",
    "Business details may require independent verification."
  ]
};

// 6. Return output for AI Agent
return [
  {
    json: {

      research_topic:
        researchContext.research_topic,

      business_category:
        researchContext.business_category,

      country:
        researchContext.country,

      business_count:
        businesses.length,

      total_reviews_sampled:
        totalReviewsSampled,

      average_rating:
        averageRating,

      businesses:
        businesses,

      ai_input:
        JSON.stringify(aiData),

      generated_at:
        new Date().toISOString(),

      data_status:
        businesses.length > 0
          ? "Ready for AI Analysis"
          : "No business records found",

      diagnostic:
        businesses.length === 0
          ? {
              records_received: records.length,
              first_record: records[0] || null
            }
          : null
    }
  }
];

// ===========================================
// SERPAPI BUSINESS VALIDATION & CLASSIFICATION
// n8n Code Node
// Mode: Run Once for Each Item
// ===========================================

// 1. Data from SerpApi
const response = $json;

// 2. Original business from Loop Over Items
const original = $("Loop Over Items").item.json;

// 3. Helper functions
function clean(value) {
  if (value === undefined || value === null) {
    return "";
  }

  return String(value)
    .toLowerCase()
    .normalize("NFKC")
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function number(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function similarity(a, b) {
  const first = clean(a);
  const second = clean(b);

  if (!first || !second) return 0;
  if (first === second) return 1;

  const wordsA = new Set(first.split(" "));
  const wordsB = new Set(second.split(" "));

  const intersection = [...wordsA]
    .filter(word => wordsB.has(word)).length;

  const union = new Set([...wordsA, ...wordsB]).size;

  return union ? intersection / union : 0;
}

// 4. Extract results from SerpApi
let results = [];

if (Array.isArray(response.local_results)) {
  results = response.local_results;
} else if (response.place_results) {
  results = [response.place_results];
} else if (response.title) {
  results = [response];
}

// 5. Original business details
const originalName =
  original.business_name ||
  original.place_name ||
  "";

const originalAddress = original.address || "";

const originalPlaceId = original.place_id || "";

const originalType =
  original.business_type ||
  "";

const researchContext = original.research_context || {};

// 6. Validate each search result
const candidates = results.map(result => {

  const nameScore = similarity(
    originalName,
    result.title
  );

  const addressScore = similarity(
    originalAddress,
    result.address
  );

  const categoryScore = similarity(
    originalType,
    result.type
  );

  const idMatch = Boolean(
    originalPlaceId &&
    result.place_id &&
    String(originalPlaceId) === String(result.place_id)
  );

  // Weighted matching score
  let score =
    nameScore * 0.65 +
    addressScore * 0.25 +
    categoryScore * 0.10;

  // Exact Place ID is strong evidence
  if (idMatch) {
    score = 1;
  }

  return {
    result,
    score,
    nameScore,
    addressScore,
    categoryScore,
    idMatch
  };
});

// 7. Find the strongest matching business
candidates.sort((a, b) => b.score - a.score);

const best = candidates[0] || null;

// 8. Classification
let status = "invalid";
let reason = "No matching business found";

if (best) {
  if (best.idMatch) {
    status = "valid";
    reason = "Exact Place ID match";
  } else if (
    best.nameScore >= 0.75 &&
    best.score >= 0.60
  ) {
    status = "valid";
    reason = "Strong name and supporting field match";
  } else if (best.score >= 0.35) {
    status = "needs_review";
    reason = "Partial match; manual verification recommended";
  } else {
    status = "invalid";
    reason = "Insufficient evidence of a business match";
  }
}

// 9. Extract the selected result
const place = best?.result || {};

// 10. Return structured validation result
return {
  json: {

    research_context: researchContext,

    original_business: {
      business_name: originalName,
      business_type: originalType,
      address: originalAddress,
      place_id: originalPlaceId,
      google_overall_rating:
        original.google_overall_rating ?? null,
      google_total_review_count:
        original.google_total_review_count ?? null,
      customer_reviews:
        original.customer_reviews || []
    },

    validation: {
      status: status,
      is_valid: status === "valid",
      reason: reason,

      confidence_score: best
        ? Number(best.score.toFixed(3))
        : 0,

      name_similarity: best
        ? Number(best.nameScore.toFixed(3))
        : 0,

      address_similarity: best
        ? Number(best.addressScore.toFixed(3))
        : 0,

      category_similarity: best
        ? Number(best.categoryScore.toFixed(3))
        : 0,

      place_id_match: best?.idMatch || false,

      candidates_checked: results.length
    },

    classification: {
      original_category: originalType,
      serpapi_category: place.type || null,
      serpapi_types: Array.isArray(place.types)
        ? place.types
        : []
    },

    // Verified/enriched SerpApi information
    serpapi_result: {

      business_name: place.title || null,

      business_type: place.type || null,

      address: place.address || null,

      rating: number(place.rating),

      reviews_count: number(place.reviews),

      phone: place.phone || null,

      website: place.website || null,

      place_id: place.place_id || null,

      data_id: place.data_id || null,

      reviews_link: place.reviews_link || null,

      google_maps_url:
        place.place_id_search || null,

      gps_coordinates:
        place.gps_coordinates || null
    },

    data_source: {
      original: "Apify Google Maps Scraper",
      validation: "SerpApi Google Maps"
    }
  }
};

/**
