const topic = String(
  form["Research Topic"] || "Market Research"
);

const category = String(
  form["Catagory"] ||
  form["Category"] ||
  "Business Research"
);

const countryCode = String(
  form["What is your Country"] || "BD"
);

const country =
  countryCode.toLowerCase() === "bd"
    ? "Bangladesh"
    : countryCode;

// Escape text for safe HTML insertion
function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// Basic Markdown fallback
function markdownToHtml(markdown) {
  return escapeHtml(markdown)
    .replace(/^### (.+)$/gm, "<h3>$1</h3>")
    .replace(/^## (.+)$/gm, "<h2>$1</h2>")
    .replace(/^# (.+)$/gm, "<h1>$1</h1>")
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\n\n/g, "</p><p>")
    .replace(/\n/g, "<br>");
}

let content = reportHtml;

if (!content && reportMarkdown) {
  content = "<p>" + markdownToHtml(reportMarkdown) + "</p>";
}

if (!content) {
  content = "<p>No market research report was generated.</p>";
}

